1. First, create a new project and initialize it with npm:

```bash
mkdir my-discord-bot
cd my-discord-bot
npm init -y
```

2. Install Discord.js and the `discord-slash` package:

```bash
npm install discord.js discord-slash @discordjs/slash
```

3. Create a new file named `index.js` and add the following code:

```javascript
const { Client, Intents, SlashCommandBuilder } = require('discord.js');
const { SlashCommandBuilder } = require('@discordjs/slash');
const { readdirSync } = require('fs');

const client = new Client({ intents: [Intents.FLAGS.Guilds, Intents.FLAGS.GuildMessages, Intents.FLAGS.GuildMembers, Intents.FLAGS.Bans] });
const commands = new SlashCommandBuilder();

client.commands = new Map();

const commandFiles = readdirSync('./commands').filter(file => file.endsWith('.js'));

for (const file of commandFiles) {
  const command = require(`./commands/${file}`);
  client.commands.set(command.name, command);
}

commands
  .addCommand(new SlashCommandBuilder()
    .setName('ban')
    .setDescription('Bans a user from the server')
    .addUserOption(option => option.setName('user').setDescription('The user to ban').setRequired(true))
    .addStringOption(option => option.setName('reason').setDescription('The reason for the ban').setRequired(false))
  )
  .toJSON();

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const command = client.commands.get(interaction.commandName);

  if (!command) return;

  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    await interaction.reply({ content: 'There was an error trying to execute that command!', ephemeral: true });
  }
});

client.login('YOUR_BOT_TOKEN');
```

Replace `'YOUR_BOT_TOKEN'` with your bot token.

4. Create a new folder named `commands` and add a new file named `ban.js` inside it:

```javascript
module.exports = {
  name: 'ban',
  description: 'Bans a user from the server',
  async execute(interaction) {
    const member = interaction.options.getMember('user');
    const reason = interaction.options.getString('reason');

    await member.ban({ reason });

    await interaction.reply(`${member.user.tag} was banned from the server. Reason: ${reason || 'No reason provided.'}`);
  },
};
```

5. Start the bot:

```bash
node index.js
```

